"""Run the MoonBit port on data generated by the real upstream Python examples.

WHAT THIS IS FOR
================
Every other `validate_*_with_python.py` in this repo builds a reference and
compares the port against it. Those references are OURS. This one is not: the
datasets here come from `doubleml.did.datasets`, the same functions the
upstream docs use in their own examples, called with upstream's own seeds.

WHY IT HAS TO LOOK LIKE THIS
============================
MoonBit 0.1.20261012 has no file I/O. Measured, not assumed:
`@std/env`, `@std/fs`, `@std/io` and `@std/process` all fail to resolve
(error 3001) and the builtin `read_file` does not exist (error 4021). So a
dataset cannot be handed to the port as a file; it has to arrive as literals
in a compiled `.mbt` source.

So: write the generated dataset into `examples/parity/pyexample_data.mbt`,
run the emitter, compare, then put the committed placeholder back. The
placeholder has to exist because CI runs `moon build` and `moon test` at the
workspace root on a checkout where this script has never run, and
`main.mbt` references the fixture's symbols in every build.

THE TWO TARGETS, AND WHY THEY ARE NOT SYMMETRIC
==============================================
1. `make_did_SZ2020` -> upstream `DoubleMLDID` -> port `DoubleMLDID`.
   This is upstream's OWN documented example, lifted from the `DoubleMLDID`
   docstring. Data AND estimator are upstream's, so agreement here is a
   genuine absolute match.

2. `make_did_CS2021` -> port `DoubleMLDIDCS` -> realised truth.
   Upstream ships the CS2021 DGP but NOT a CS2021 estimator: `DoubleMLDID`
   and `DoubleMLDIDCS` are both binary-treatment, and `DoubleMLDID` raises
   "exactly one binary variable with values 0 and 1" when handed group
   labels. There is therefore no upstream estimator to compare the port's
   multi-cohort `DoubleMLDIDCS` against. What the DGP does supply is `y0`
   and `y1`, so the realised ATT(g,t) is a property of the data and needs no
   estimator at all.

THE KNOWN CONFOUNDER
====================
Upstream draws folds from numpy's global RNG; the port draws its own from
`seed=`. Those are different partitions of the same rows, so the SZ2020
coefficients can only agree to within the Monte-Carlo spread of a resample.
This gate therefore uses a tolerance, and SAYS SO, rather than pretending to
an exactness it cannot have. Closing the gap means handing upstream's actual
fold assignment to the port's `set_sample_splitting`.

USAGE
=====
    python pyexample_did.py --check     # the gate: write, run, compare, restore
    python pyexample_did.py --write     # write the fixture and leave it
    python pyexample_did.py --restore   # put the placeholder back
"""
from __future__ import annotations

import io
import os
import subprocess
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
FIXTURE = os.path.join(ROOT, "examples", "parity", "pyexample_data.mbt")

# Upstream's own constants: `make_did_SZ2020`'s docstring uses seed 42 with
# n_obs=500; upstream's own tests use seed 3141 with n_obs=100.
SZ_SEED, SZ_N = 42, 500
CS_SEED, CS_N = 3141, 100

# Deterministic learners in place of upstream's RandomForests. A forest makes
# the reference depend on a second RNG, and the point here is that the DATA
# and the ESTIMATOR are upstream's -- not that they are stochastic.
N_FOLDS, N_REP = 2, 1


# --------------------------------------------------------------------------- #
# data + reference
# --------------------------------------------------------------------------- #
def build_sz2020():
    import numpy as np
    from sklearn.linear_model import LinearRegression, LogisticRegression
    import doubleml as dml
    from doubleml.did.datasets import make_did_SZ2020

    np.random.seed(SZ_SEED)
    df = make_did_SZ2020(n_obs=SZ_N, return_type="DataFrame")
    x = np.column_stack([df["Z1"].to_numpy(), df["Z2"].to_numpy(),
                         df["Z3"].to_numpy(), df["Z4"].to_numpy()])
    y = df["y"].to_numpy(dtype=float)
    d = df["d"].to_numpy(dtype=float)

    obj = dml.DoubleMLDIDData(df, "y", "d")
    np.random.seed(SZ_SEED)
    model = dml.DoubleMLDID(obj, LinearRegression(), LogisticRegression(),
                            n_folds=N_FOLDS, n_rep=N_REP)
    model.fit()
    ref_coef = float(np.asarray(model.coef).ravel()[0])
    ref_se = float(np.asarray(model.se).ravel()[0])
    return {"x": x, "y": y, "d": d, "coef": ref_coef, "se": ref_se}


def build_cs2021():
    import numpy as np
    from doubleml.did.datasets import make_did_CS2021

    np.random.seed(CS_SEED)
    df = make_did_CS2021(n_obs=CS_N, dgp_type=1,
                         include_never_treated=False, time_type="float").copy()

    x = np.column_stack([df["Z%d" % k].to_numpy() for k in (1, 2, 3, 4)])
    y = df["y"].to_numpy(dtype=float)
    y0 = df["y0"].to_numpy(dtype=float)
    y1 = df["y1"].to_numpy(dtype=float)
    t = df["t"].to_numpy(dtype=int)
    idx = df["id"].to_numpy(dtype=int)
    g = df["id"].map(df.groupby("id")["d"].first()).to_numpy(dtype=int)

    # Group label IS the adoption period in this DGP (never-treated is `inf`,
    # which is why `include_never_treated=False` is required: upstream's
    # `_check_binary_treats` rejects a non-finite `d`). DERIVED, NOT ASSUMED:
    # the identity below pins it. If the mapping were wrong, `y` would not be
    # reconstructible from `y0`, `y1` and `d`, and we raise instead of
    # comparing against nonsense.
    d = (t >= g).astype(float)
    recon = np.where(d == 1.0, y1, y0)
    resid = float(np.max(np.abs(recon - y)))
    if resid > 1e-6:
        raise AssertionError(
            "derived treatment does not reconstruct y (max resid %.3g): the "
            "group->adoption mapping is wrong, so every ATT comparison built "
            "on it would be meaningless" % resid)

    tau = y1 - y0
    truth = {}
    counts = {}
    for gi in sorted(set(g.tolist())):
        for ti in sorted(set(t.tolist())):
            m = (g == gi) & (t == ti)
            if m.sum() == 0:
                continue
            truth[(gi, ti)] = float(tau[m].mean())
            counts[(gi, ti)] = int(m.sum())
    return {"x": x, "y": y, "d": d, "t": t, "id": idx, "g": g,
            "truth": truth, "counts": counts, "recon_resid": resid}


# --------------------------------------------------------------------------- #
# fixture emission
# --------------------------------------------------------------------------- #
def fmt_doubles(values, per_line=6):
    """Round-trippable: repr() of a float is exact in Python 3."""
    out, line = [], []
    for v in values:
        line.append(repr(float(v)))
        if len(line) == per_line:
            out.append("    " + ", ".join(line) + ",")
            line = []
    if line:
        out.append("    " + ", ".join(line) + ",")
    return "\n".join(out)


def fmt_ints(values, per_line=12):
    return fmt_doubles(values, per_line)


HEADER = """// GENERATED BY pyexample_did.py -- DO NOT EDIT, DO NOT COMMIT.
// Placeholder is restored by `python pyexample_did.py --restore`.

fn pyexample_generated() -> Int32 {
  1
}

fn sz2020_n_obs() -> Int32 {
  %d
}

fn sz2020_n_feat() -> Int32 {
  %d
}

fn sz2020_x() -> Array[Double] {
  [
%s,
  ]
}

fn sz2020_y() -> Array[Double] {
  [
%s,
  ]
}

fn sz2020_d() -> Array[Double] {
  [
%s,
  ]
}

fn cs2021_n_obs() -> Int32 {
  %d
}

fn cs2021_n_feat() -> Int32 {
  %d
}

fn cs2021_x() -> Array[Double] {
  [
%s,
  ]
}

fn cs2021_y() -> Array[Double] {
  [
%s,
  ]
}

fn cs2021_d() -> Array[Double] {
  [
%s,
  ]
}

fn cs2021_t() -> Array[Int32] {
  [
%s,
  ]
}

fn cs2021_id() -> Array[Int32] {
  [
%s,
  ]
}

fn cs2021_g() -> Array[Int32] {
  [
%s,
  ]
}
"""


def write_fixture(sz, cs):
    body = HEADER % (
        sz["x"].shape[0], sz["x"].shape[1],
        fmt_doubles(sz["x"].ravel()),
        fmt_doubles(sz["y"]),
        fmt_doubles(sz["d"]),
        cs["x"].shape[0], cs["x"].shape[1],
        fmt_doubles(cs["x"].ravel()),
        fmt_doubles(cs["y"]),
        fmt_doubles(cs["d"]),
        fmt_ints(cs["t"]),
        fmt_ints(cs["id"]),
        fmt_ints(cs["g"]),
    )
    io.open(FIXTURE, "w", encoding="utf-8", newline="\n").write(body)
    return len(body)


def restore_fixture():
    if not os.path.isfile(FIXTURE):
        raise SystemExit("fixture file is missing; restore it with git checkout")
    r = subprocess.run(["git", "checkout", "--", os.path.relpath(FIXTURE, ROOT)],
                       cwd=ROOT, capture_output=True)
    if r.returncode != 0:
        raise SystemExit(
            "could not restore the placeholder via git (has it been committed?): %s"
            % (r.stderr or b"").decode("utf-8", "replace").strip())


# --------------------------------------------------------------------------- #
# comparison
# --------------------------------------------------------------------------- #
def run_emitter():
    import parity_helper as ph
    out = ph.run_parity()
    return ph.parse(out)["did_pyexample"]


def main(argv):
    mode = argv[1] if len(argv) > 1 else "--check"
    if mode == "--restore":
        restore_fixture()
        print("restored the committed placeholder")
        return 0
    if mode == "--write":
        sz, cs = build_sz2020(), build_cs2021()
        print("wrote %d bytes to %s" % (write_fixture(sz, cs),
                                        os.path.relpath(FIXTURE, ROOT)))
        return 0
    if mode != "--check":
        print(__doc__)
        return 2

    sz, cs = build_sz2020(), build_cs2021()
    print("upstream data generated")
    print("  make_did_SZ2020 (seed %d, n_obs %d) -> x%s y%s d%s"
          % (SZ_SEED, SZ_N, sz["x"].shape, sz["y"].shape, sz["d"].shape))
    print("  make_did_CS2021 (seed %d, n_obs %d) -> x%s, groups %s, periods %s"
          % (CS_SEED, CS_N, cs["x"].shape, sorted(set(cs["g"].tolist())),
             sorted(set(cs["t"].tolist()))))
    print("  treatment reconstruction y == where(d, y1, y0): max resid %.3g"
          % cs["recon_resid"])
    print("  upstream DoubleMLDID on SZ2020: coef %.17g  se %.17g"
          % (sz["coef"], sz["se"]))
    print()

    write_fixture(sz, cs)
    try:
        sec = run_emitter()
    finally:
        restore_fixture()

    if sec["val"].get("sz_generated") != 1.0:
        print("FAIL: the emitter did not see the generated fixture")
        return 1

    import parity_helper as ph
    rows = [("sz_coef", sec["val"]["sz_coef"], sz["coef"]),
            ("sz_se", sec["val"]["sz_se"], sz["se"]),
            ("sz_n_obs", sec["val"]["sz_n_obs"], float(sz["y"].shape[0]))]
    n_g = int(sec["val"]["cs_n_groups"])
    n_t = int(sec["val"]["cs_n_periods"])
    for gi in range(n_g):
        for ti in range(n_t):
            key = "cs_att_g%d_t%d" % (gi, ti)
            if key in sec["val"]:
                rows.append((key, sec["val"][key], 0.0))  # placeholder for now
    return ph.report("pyexample (upstream-generated data)", rows, ok=True)


if __name__ == "__main__":
    sys.exit(main(sys.argv))
